import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {build} from 'esbuild';
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const files=[];function scan(p){for(const n of fs.readdirSync(p)){const f=path.join(p,n);fs.statSync(f).isDirectory()?scan(f):files.push(f);}}for(const p of ['src','racing','frozen','tests','tools','models','vendor'])scan(p);files.push('index.template.html','build.mjs','package.json');files.sort();const inputs=Object.fromEntries(files.map(f=>[f,sha(fs.readFileSync(f))]));const provenance=JSON.parse(fs.readFileSync('evidence/BASELINE_PROVENANCE.json'));const identity={edition:'F1M China & Suzuka / 33',sourceRevision:sha(JSON.stringify(inputs)),inputs,physics:'Frozen P1 core and controller; physical pit, AI, resources, weather and weekend adapters v15',safetyCarVersion:'SC2.1',safetyCarAsset:sha(fs.readFileSync('models/F1M_SafetyCar_SC1.glb')),baseline:provenance.identity.sourceRevision,car163:sha(fs.readFileSync('models/car163.glb')),p1Acceptance:'NOT ACCEPTED'};
const options={bundle:true,format:'iife',platform:'browser',target:'es2020',write:false,minify:false,legalComments:'none'};const physicsWorker=(await build({...options,entryPoints:['src/physics-worker32.js']})).outputFiles[0].text;const worker=(await build({...options,entryPoints:['src/race-worker.js'],define:{PHYSICS_WORKER_SOURCE32:JSON.stringify(physicsWorker)}})).outputFiles[0].text;const app=(await build({...options,entryPoints:['src/app.js'],define:{RACE_WORKER_SOURCE:JSON.stringify(worker),BUILD:JSON.stringify(identity),WATCH_UI_CSS_24:JSON.stringify(fs.readFileSync('src/watch-ui24.css','utf8'))}})).outputFiles[0].text;
let html=fs.readFileSync('index.template.html','utf8').replace('/*RACE_UI_21*/',()=>fs.readFileSync('src/race-ui21.css','utf8'));for(const [tag,f]of [['ENGINE','vendor/engine.bundle.js'],['CPU','src/cpu-track-renderer.js'],['HAND','src/grip-hand.js'],['RIG','src/driver-rig.js']])html=html.replace('/*'+tag+'*/',()=>fs.readFileSync(f,'utf8').replace(/<\/script/gi,'<\\/script'));html=html.replace('__MODEL__',fs.readFileSync('models/car163.glb').toString('base64')).replace('__SAFETY_MODEL__',fs.readFileSync('models/F1M_SafetyCar_SC1.glb').toString('base64')).replace('/*APP*/',()=>app.replace(/<\/script/gi,'<\\/script'));fs.mkdirSync('dist',{recursive:true});fs.writeFileSync('dist/index.html',html);fs.writeFileSync('F1M_China_Suzuka_33.html',html);identity.htmlSha256=sha(html);identity.htmlBytes=Buffer.byteLength(html);fs.writeFileSync('evidence/BUILD.json',JSON.stringify(identity,null,2));console.log(JSON.stringify({bytes:identity.htmlBytes,htmlSha256:identity.htmlSha256,sourceRevision:identity.sourceRevision}));

