                                        import{SCHEMA}from'./contracts.js';
const keys='schema version m Iz a b h tf tr rollFront g length width R Iw CdA ClA aeroFront rho mu loadExp tau steerMax steerRate steerLag pedalRate ratios finalRatio driveEff enginePower brakeF brakeR capacity deployW regenW motorTorque deployEff regenEff regenFraction auxW Cs Cc Hsc Hst Hca wearK damageK damageT dt substeps contactE contactMu Kv Ki Kpsi Ky Kr feature airT trackT'.split(' ');
export function validateConfig(c       ){for(const k of keys)if(!(k in c))throw Error('MISSING_CONFIG:'+k);for(const k of Object.keys(c))if(!keys.includes(k))throw Error('UNKNOWN_CONFIG:'+k);for(const k of keys.filter(k=>!['schema','version','feature','ratios'].includes(k)))if(typeof(c       )[k]!=='number'||!Number.isFinite((c       )[k]))throw Error('NUMERIC_CONFIG:'+k);if(c.schema!==SCHEMA||typeof c.version!=='string'||!c.version)throw Error('VERSION');const ranges    ={m:[500,1500],Iz:[500,5000],a:[.5,3],b:[.5,3],h:[.1,.8],tf:[1.2,2.2],tr:[1.2,2.2],length:[4,7],width:[1.5,2.2],R:[.2,.5],Iw:[.2,4],CdA:[.3,3],ClA:[0,8],rho:[.8,1.5],mu:[.01,3],steerMax:[.1,.8],steerRate:[.1,2],steerLag:[.01,.5],pedalRate:[.5,20],tau:[0,.2],dt:[1/240,1/30],substeps:[1,8]};for(const[k,[lo,hi]]of Object.entries(ranges)      )if((c       )[k]<lo||(c       )[k]>hi)throw Error('RANGE:'+k);for(const k of['driveEff','deployEff','regenEff'])if((c       )[k]<=0||(c       )[k]>1)throw Error('EFFICIENCY:'+k);for(const k of['rollFront','aeroFront','regenFraction','contactE'])if((c       )[k]<0||(c       )[k]>1)throw Error('FRACTION:'+k);for(const k of['capacity','Cs','Cc','finalRatio'])if((c       )[k]<=0)throw Error('POSITIVE:'+k);for(const k of['brakeF','brakeR','enginePower','deployW','regenW','motorTorque','auxW','Hsc','Hst','Hca','wearK','damageK','contactMu'])if((c       )[k]<0)throw Error('NONNEGATIVE:'+k);if(!Number.isInteger(c.substeps))throw Error('INTEGER_SUBSTEPS');if(!Array.isArray(c.ratios)||c.ratios.length!==8||c.ratios.some((v,i)=>!Number.isFinite(v)||v<=0||(i>0&&v>=c.ratios[i-1])))throw Error('GEARS');if(Object.keys(c.feature).sort().join()!=='fade,flight,grade,reverse,wake'||Object.values(c.feature).some(v=>v!==false))throw Error('UNSPECIFIED_FEATURE');}

