export const SCHEMA='P1-IF01-09/1.0.0';




export const clamp=(v       ,a       ,b       )=>Math.max(a,Math.min(b,v));
export const wrap=(v       )=>Math.atan2(Math.sin(v),Math.cos(v));
export function validateCommand(c        ,s      )            {const keys=['tick','expires','throttle','brake','steer','gear','energy','planId'];if(Object.keys(c).some(k=>!keys.includes(k)))return'UNKNOWN_COMMAND_FIELD';if(![c.tick,c.expires,c.throttle,c.brake,c.steer].every(Number.isFinite))return'NONFINITE_COMMAND';if(c.tick!==s.tick||c.expires<s.tick)return'STALE_COMMAND';if(c.throttle<0||c.throttle>1||c.brake<0||c.brake>1)return'PEDAL_RANGE';if(c.gear!==undefined&&(!Number.isInteger(c.gear)||c.gear<1||c.gear>8))return'GEAR_RANGE';return null;}

