export const ROUND_KEYS23=['bahrain','canal','ridge','shanghai','suzuka'],POINTS23=[10,8,6,4,2,1],TEAM_CARS23={1:[1,2],2:[3,4],3:[5,6]};
export function newChampionship23(team=1,laps=0,id=String(Date.now())){if(!TEAM_CARS23[team]||![0,1,2,4,5,6].includes(laps))throw Error('เลือกทีมและจำนวนรอบ');return {version:1,id,team,laps,round:0,history:[],plans:{},created:new Date().toISOString()};}
export function validateChampionship23(s){if(!s||s.version!==1||typeof s.id!=='string'||s.id.length>80||!TEAM_CARS23[s.team]||![0,1,2,4,5,6].includes(s.laps)||!Number.isInteger(s.round)||s.round<0||s.round>=ROUND_KEYS23.length||!Array.isArray(s.history)||s.history.length>ROUND_KEYS23.length)throw Error('ข้อมูลรายการไม่ถูกต้อง');const seen=new Set();for(const h of s.history){if(!Number.isInteger(h.round)||h.round<0||h.round>=ROUND_KEYS23.length||seen.has(h.round)||h.track!==ROUND_KEYS23[h.round]||!Array.isArray(h.results)||h.results.length!==6||new Set(h.results.map(x=>x.id)).size!==6||new Set(h.results.map(x=>x.position)).size!==6||h.results.some(x=>!Number.isInteger(x.id)||x.id<1||x.id>6||(x.status==='DNF'?x.time!==null:!Number.isFinite(x.time)||x.time<=0)||!Number.isInteger(x.position)||x.position<1||x.position>6))throw Error('ผลการแข่งขันไม่ถูกต้อง');seen.add(h.round);}if(s.round>s.history.length||s.history.some((h,i)=>h.round!==i))throw Error('ลำดับสนามไม่ถูกต้อง');return structuredClone(s);}
export function recordRound23(s,frame,analysis=null){if(!frame.finished||frame.stop||frame.weekend?.stage!=='RACE'||s.history.some(h=>h.round===s.round)||frame.track23?.key!==ROUND_KEYS23[s.round])return false;const rows=frame.results;if(!rows||rows.length!==6||rows.some(r=>!r.retired&&(!r.finished||!Number.isFinite(r.time))))return false;s.history.push({round:s.round,track:frame.track23.key,results:rows.map((r,i)=>({id:r.id,name:r.name,position:i+1,status:r.retired?'DNF':'FINISHED',time:r.retired?null:r.time+(r.penalty??0),elapsed:r.retired?null:r.time,penalty:r.penalty??0,points:r.retired?0:POINTS23[i],bestLap:r.bestLap,stops:r.stops??0})),analysis});return true;}
export function standings23(s){const rows=Array.from({length:6},(_,i)=>({id:i+1,name:'#'+(i+1),points:0,wins:0,finishes:[]}));for(const h of s?.history??[])for(const result of h.results){const row=rows[result.id-1];row.name=result.name;row.points+=result.status==='DNF'?0:(result.points??POINTS23[result.position-1]??0);row.wins+=result.status!=='DNF'&&result.position===1?1:0;row.finishes.push(result.position);}return rows.sort((a,b)=>b.points-a.points||b.wins-a.wins||Math.min(...a.finishes,99)-Math.min(...b.finishes,99)||a.id-b.id);}
export function teamStandings23(s){const d=standings23(s);return Object.entries(TEAM_CARS23).map(([id,cars])=>({id:Number(id),points:d.filter(x=>cars.includes(x.id)).reduce((a,x)=>a+x.points,0)})).sort((a,b)=>b.points-a.points||a.id-b.id);}

