 profile(cpu=false){return {shadows:!cpu&&this.mode!=='LOW',shadowSize:this.mode==='LOW'?512:1024,detailDistance:cpu?32:this.mode==='LOW'?45:this.mode==='HIGH'?160:100};}
}
