 return {cameraBarriers,structuresOcclusion:new CameraOcclusion(T,structures),structures:structures.length,roadMaterial:mats.get('#343d43'),length:circuit.length,width:circuit.width,staticBatches:batches.size,treeCount:trees.length,occlusion:new CameraOcclusion(T,trees)};
