const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createResults24(){const panel=document.createElement('section');panel.id='results24';panel.hidden=true;document.body.append(panel);return panel;}
