 const teamLinks=document.createElement('div');teamLinks.id='team-links24';teamLinks.innerHTML='<button id="plans-link24">แผนยางและพิตสองคัน</button><button id="orders-link24">เป้าหมายและแผนร่วมทีม</button>';$('engineer-panel').prepend(teamLinks);$('plans-link24').onclick=()=>championshipUI.open('plans');$('orders-link24').onclick=()=>championshipUI.open('orders');
 const drs=document.createElement('div');drs.id='drs24';drs.setAttribute('aria-label','สถานะ DRS');document.querySelector('.driver-info').append(drs);const zoneNote=document.createElement('div');zoneNote.id='map-caption24';zoneNote.textContent='แผนที่ · แตะรถเพื่อเลือก';document.body.append(zoneNote);
 const orbit=document.createElement('button');orbit.id='replay-inspect24';orbit.textContent='หยุดภาพ / หมุนดู';$('replay-panel').insertBefore(orbit,$('replay-live'));orbit.onclick=inspectReplay;const hint=document.createElement('small');hint.id='inspect-hint24';hint.textContent='ลากหมุน · จีบเพื่อซูม · ลูกศร/ปุ่ม + − ใช้ได้';hint.hidden=true;$('replay-panel').append(hint);
 for(const b of nav.querySelectorAll('[data-view24]'))b.onclick=()=>{const view=b.dataset.view24;for(const button of nav.querySelectorAll('[data-view24]'))button.setAttribute('aria-pressed',String(button===b));if(view==='results'&&getState().payload)results(getState().payload);if(view==='watch')raceUI.close();else raceUI.open(view==='team'?'team':'results',b);};
 $('map-toggle21').hidden=true;$('map').hidden=false;$('map').width=372;$('map').height=230;$('map').setAttribute('aria-label','มินิแมพ แตะรถเพื่อเลือกติดตาม กด Enter เพื่อเปิดรายชื่อรถ');$('map').tabIndex=0;

 $('results24').innerHTML='<h3 id="timing-title24">อันดับขณะนี้</h3><p id="timing-note24" class="muted24"></p><table class="timing24"><thead><tr><th>P</th><th>นักขับ</th><th>ระยะ / เวลา</th></tr></thead><tbody id="timing-rows24"></tbody></table><div class="result-links24"><button id="season-link24">รายการ / คะแนนสะสม</button><button id="analysis-link24">กราฟและคลิปย้อนหลัง</button></div>';
